def add(w,n,title,stem,options,explanations,why,typ='conceptual',difficulty='easy',assumptions=None,steps=None,formulas=None,kinds=None,locs=None,conflict=None):
 assert len(options)==len(explanations)==4 and len(set(options))==4
 bid=f'ASSIGN-W{w:02d}';qid=f'{bid}-Q{n:03d}';oid=f'{bid}-Q{n:02d}';item=ITEMS[oid];cid=f'{bid}-C{n:03d}';pages=item['physicalPages'];b=BATCHES.setdefault(w,{'schemaVersion':'1.0.0','batchId':bid,'authorId':WHO,'questions':[],'concepts':[],'coverageNote':'Every original item has a source-linked qualified adaptation. Immutable original records preserve supplied prompts, options and keys. All adaptations remain drafts pending independent review.'});assert qid not in [q['id']for q in b['questions']]
 citations=[]
 for i,p in enumerate(pages):
  loc=(locs or {}).get(p,f'Week {w}, printed item {n}: '+('prompt and choices'if i==0 else 'continued item or explanation'))
  citations.append({'slideId':f'assignments-p{p:04d}','sourceId':'assignments','sourceSha256':SHA,'physicalPage':p,'kind':(kinds or {}).get(p,'statement'),'locator':f'Assignment physical PDF page {p}, printed footer {next(x["printedPageNumber"]for x in H["pages"]if x["physicalPage"]==p)}: {loc}.','evidenceText':item['originalSourceText'],'role':'conflict'if conflict else 'premise','region':None})
 # Fixed IDs encode no answer position: option text order is deterministically shuffled for authored presentation.
 order=[(n+w+i)%4 for i in range(4)];opts=[{'id':f'o{i+1}','text':options[i]}for i in order]
 q={'id':qid,'version':1,'status':'draft','authorId':WHO,'stem':stem,'selectionMode':'single','type':typ,'difficulty':difficulty,'cognitiveSkill':'numerical'if typ=='numerical'else 'synthesis'if typ=='derivation'else 'application'if typ in ('scenario','diagram')else 'conceptual','week':w,'lectureId':None,'topic':f'Assignment Week {w}','subtopic':title,'tags':['assignment',f'week-{w}',title.lower().replace(' ','-')],'conceptIds':[cid],'assumptions':assumptions or [],'options':opts,'correctOptionIds':['o1'],'citations':citations,'solution':{'justification':why,'optionExplanations':{f'o{i+1}':e for i,e in enumerate(explanations)},'steps':steps or [],'formulas':formulas or [],'simpleExplanation':why,'memoryAid':None,'misconceptions':explanations[1:],'examTraps':[],'prerequisiteConceptIds':[]},'origin':'assignment_adapted','reviewIds':[],'assignmentSourceItemId':oid,'originalRecordPath':f'audits/assignment-originals/{oid}.json','originalRecordSha256':sha(f'audits/assignment-originals/{oid}.json'),'difficultyRationale':'Direct distinction or one short operation under explicit assumptions.'if difficulty=='easy'else 'Requires combining the stated model, multiple operations or a nontrivial source qualification.'}
 if conflict:q['conflictResolution']={'status':'explicit-qualification-awaiting-independent-review','sourceId':'assignments','sourceSha256':SHA,'questionVersion':1,'sourceClaim':conflict,'basis':why,'method':'Preserve the literal original outside the study pool and assess only this explicitly qualified adaptation. No global source resolution.'}
 b['questions'].append(q);b['concepts'].append({'id':cid,'title':title,'description':why,'slideIds':[f'assignments-p{p:04d}'for p in pages],'questionIds':[qid],'status':'drafted','topic':q['topic'],'subtopic':title,'prerequisiteConceptIds':[],'examinationAngles':[typ,'assumption_or_misconception']});write(f'data/question-batches/{bid}.json',b)
 return q
# Week 1: fundamentals, with policy/state and abstraction qualifications explicit.
add(1,1,'Fictional law priority','In the assignment’s fictional Asimov framework, which highest-priority prohibition directly rules out choosing self-preservation at the cost of harming a human?',['The First Law’s prohibition on harming a human.','The Second Law’s duty to obey orders, considered without its First Law exception.','The Third Law’s self-preservation duty, considered without its higher-law exceptions.','A rule assigning equal priority to obedience, human protection and self-preservation.'],['The First Law directly prohibits the harm; lower-priority duties cannot override it.','Obedience is subordinate to the First Law, not an independent justification for harm.','Self-preservation is qualified by the higher laws rather than overriding them.','The fictional laws have a priority hierarchy, not equal weights.'],'The direct highest-priority prohibition is the First Law. This is course fiction, not a real robot safety standard.',assumptions=['Interpret the fictional framework used in the assignment, not engineering safety certification.'])
add(1,2,'Offline model calibration','A task is programmed offline in a CAD cell while production continues. Before executing it on the physical robot, which remaining task is directly needed to align model and physical target coordinates?',['Calibrate the relevant robot, tool and work-frame relationships.','Replace CAD coordinates with raw encoder counts without establishing their geometric relation.','Increase the controller’s execution speed so coordinate offsets become negligible.','Replay the simulation repeatedly without comparing any physical reference.'],['Calibration establishes the relevant model-to-physical geometry.','Encoder values still require kinematic and frame relationships to locate targets.','Faster motion does not remove a geometric frame offset.','Simulation repetition alone does not identify a physical mismatch.'],'Offline development reduces production interruption but does not eliminate physical calibration.',typ='scenario')
add(1,3,'Overlapping learning categories','A robot learns a reward-maximizing policy represented by a deep neural network. Which classification avoids treating ML, DL and RL as disjoint categories?',['It is reinforcement learning, and the deep network can make it a deep-learning method within machine learning.','It is deep learning but cannot be reinforcement learning because its model is a neural network.','It is reinforcement learning but cannot be machine learning because its supervision is reward.','It is supervised learning solely because a neural network represents the policy.'],['Reward-based policy learning and a deep function approximator can coexist; the categories overlap.','The function approximator does not exclude a reward-based learning objective.','Learning from interaction and rewards remains machine learning.','A network architecture alone does not specify supervised labels or the learning paradigm.'],'RL describes the interaction/objective structure, while DL describes a deep neural representation; both can apply to the same ML system.',typ='scenario',assumptions=['Added example using a deep policy model; the source’s short definitions do not imply mutually exclusive categories.'])
add(1,4,'Policy memory versus Markov state','A vacuum policy uses only its current state s_t. Which ADDITIONAL property establishes that s_t is a Markov state for the controlled environment?',['Given s_t and action a_t, the next-state distribution is independent of earlier states and actions.','The policy chooses the same action whenever the same location is observed, even if hidden dirt changes future transitions.','The controller stores no previous observations, regardless of what information the state omits.','The next reward is always positive for every action available at s_t.'],['This conditional independence is the controlled Markov property.','A memoryless policy can operate in a partially observed, non-Markov observation space.','Discarding history does not make the retained state sufficient.','Reward sign is unrelated to whether past information changes transition predictions.'],'A memoryless policy is not evidence of Markov dynamics. The added state-sufficiency condition, rather than policy memory, establishes the property.',assumptions=['s_t denotes the proposed state, a_t the current action, and earlier history all preceding states/actions.'],conflict='The original infers a Markov decision process from a vacuum choosing actions only from current location; that alone does not establish a sufficient Markov state.')
add(1,5,'State-space input','For ẋ(t) = A x(t) + B u(t), x is the state vector, A the state matrix and B the input matrix. Which quantity is the externally supplied control input?',['u(t).','x(t).','ẋ(t).','A x(t).'],['u is mapped through B into the state derivative.','x describes the system state, not the separate input.','The derivative is the resulting rate of state change.','A x is the autonomous state-dependent contribution.'],'u(t) is the control input; its dimensions and physical units depend on the modeled plant.',kinds={2:'equation'},formulas=[formula('ẋ = A x + B u',{'x':'n-component state vector','ẋ':'state derivative','u':'m-component input vector','A':'n by n state matrix','B':'n by m input matrix','n,m':'positive integer state/input dimensions'},{'x,u':'plant-dependent component units','ẋ':'corresponding state units per time','A,B':'compatible mapping units','n,m':'dimensionless'},['Continuous-time linear state model; dimensions conform.'])])
add(1,6,'Gradient components','For f(x,y) = 3x² + 2xy + y², what is ∇f at (x,y) = (1,2), with components ordered as (∂f/∂x, ∂f/∂y)?',['(10, 6).','(6, 10).','(6, 4).','(8, 6).'],['The partials are 6x+2y and 2x+2y, yielding 10 and 6.','This reverses the specified component order.','This differentiates the pure-square terms but drops the mixed term.','This uses 2x rather than 2y for the mixed term in the x derivative.'],'Differentiate while holding the other variable fixed, then substitute; the gradient is (10,6).',typ='numerical',kinds={2:'equation',3:'derivation'},steps=['∂f/∂x = 6x + 2y.','∂f/∂y = 2x + 2y.','At (1,2), evaluate (6+4, 2+4) = (10,6).'],formulas=[formula('∇f = (6x+2y, 2x+2y)',{'f':'given scalar polynomial','x,y':'independent variables','∇f':'ordered vector of partial derivatives'},{'f,x,y,∇f':'dimensionless for this exercise'},['Coordinate order is x then y.'])])
add(1,7,'Probabilistic sensing','Repeated measurements of one stationary obstacle vary because of sensor noise. What does a probabilistic observation model add to the robot’s estimate?',['A representation of plausible true states and measurement uncertainty.','A guarantee that each reported range equals the true range after modeling.','A deterministic substitution of the latest raw measurement for every state hypothesis.','A rule discarding all measurements that differ from the first reading.'],['Probability can represent uncertainty and combine noisy evidence.','Modeling uncertainty does not remove the actual measurement error.','A single raw value does not retain a distribution over uncertain states.','Variation can be ordinary noise; the first reading is not necessarily truth.'],'Probabilistic models represent and reason about sensor uncertainty rather than guaranteeing exact sensing.',typ='scenario')
add(1,8,'Task-relative model fidelity','A 2D simulator represents a car as a point and ignores body shape, orientation and dynamics. If the task is to predict body clearance and turning dynamics, which assessment is justified?',['The abstraction is coarse and low-fidelity for those specified observables.','It has high fidelity for body clearance because a point has exact coordinates.','It has high fidelity for turning dynamics because the path lies in a plane.','Its fidelity for those observables is established solely by a small integration time step.'],['The quantities the task needs were removed from the model.','Exact point coordinates cannot describe omitted body extent.','Planarity alone does not supply steering or dynamic behavior.','A fine time step cannot restore missing geometric or physical state.'],'Fidelity is relative to the intended predictions: the point abstraction omits the body and dynamics required here.',typ='scenario',assumptions=['Added explicit target observables: body clearance and turning dynamics. A point model may still be suitable for another coarser task.'])
add(1,9,'Modular integration','Navigation and speech-recognition components can be developed separately and connected through agreed interfaces. Which principle is most directly illustrated?',['Modularity.','Inheritance of one component’s implementation by the other.','Replacing all components with one shared global-state routine.','Numerical discretization of continuous dynamics.'],['Separating responsibilities behind interfaces supports modular development.','Independent interacting modules need not form an inheritance hierarchy.','A monolithic shared-state routine removes the separation described.','Time or state discretization is a different design concern.'],'Separate components with defined interfaces illustrate modularity; other software principles may also support the design.')
add(1,10,'TF versus robot description','A robot application must look up a changing camera-to-base transform at a particular time. Which source distinction identifies the relevant facility?',['TF maintains frame relationships over time; URDF describes the robot’s structure.','URDF alone is the time-history buffer for measured camera poses; TF defines link materials.','TF is the mesh-format parser, while URDF is the force-control feedback loop.','Both names denote only the same static joint-limit table.'],['TF is the frame-transform facility; URDF supplies structural description rather than replacing a transform history.','This exchanges the transform and structural roles.','Neither role pairing matches the source facilities.','They have different purposes and are not just a joint-limit table.'],'Use the transform facility for time-indexed frame relationships; a structural description is not itself a live transform history.',typ='scenario',assumptions=['Conceptual roles in the source; no ROS runtime or external robot operation is executed.'])
# Week 2: kinematics and explicit repairs of defective original premises.
add(2,1,'Proper rotation constraints','A 3×3 matrix is proposed as a proper rigid-body rotation. Which condition rules it out?',['det(R) = 0.','RᵀR = I.','det(R) = +1.','R⁻¹ = Rᵀ.'],['A zero determinant is singular, whereas a rotation is invertible.','Orthogonality is required for a rotation.','Proper rotations have determinant +1.','The inverse of an orthogonal rotation is its transpose.'],'A proper rotation preserves lengths and handedness and cannot have determinant zero.',kinds={5:'equation'},formulas=[formula('RᵀR = I; det(R) = +1; R⁻¹ = Rᵀ',{'R':'3 by 3 proper rotation matrix','I':'3 by 3 identity','det':'matrix determinant'},{'R,I,det(R)':'dimensionless'},['Real orthonormal right-handed frames.'])])
add(2,2,'Homogeneous point convention','With 3D points written as homogeneous column vectors [x,y,z,1]ᵀ, which bottom row belongs to a rigid homogeneous transform?',['[0, 0, 0, 1].','[t_x, t_y, t_z, 1].','[0, 0, 0, 0].','[1, 0, 0, 0].'],['This preserves the homogeneous point coordinate 1.','That is associated with a transposed row-vector convention, not the stated column-vector layout.','It maps the final homogeneous coordinate of every point to zero.','It makes the final coordinate depend on x rather than preserving 1.'],'For column vectors, translation is in the final column and the bottom row is [0,0,0,1].',kinds={5:'equation'},assumptions=['Rigid affine transform, not a projective camera matrix.'],formulas=[formula('T = [[R,t],[0ᵀ,1]]',{'T':'4 by 4 rigid transform for column vectors','R':'3 by 3 rotation','t':'3-component translation','0':'3-component zero vector'},{'R,0,1':'dimensionless','t':'length','T':'mixed block units'},['Point represented as [x,y,z,1]ᵀ.'])])
add(2,3,'Joint coordinates versus task rank','An unconstrained serial chain has four independent revolute joints and two independent prismatic joints. Which conclusion follows without assuming its current Jacobian rank?',['It has six independent joint coordinates; a six-dimensional task rank is not guaranteed at every configuration.','It has four independent coordinates because prismatic joints do not contribute degrees of freedom.','It has eight coordinates because each prismatic joint contributes two.','It has six joint coordinates and therefore rank six at every configuration.'],['Each stated independent one-DOF joint contributes one coordinate; task rank can fall at singularities.','Each independent prismatic joint contributes one coordinate.','A prismatic joint contributes one translational coordinate, not two.','Coordinate count alone does not establish nonsingularity.'],'Joint-space dimension is six, but task-space instantaneous mobility also depends on the Jacobian.',assumptions=['No closed-loop constraints or mechanically coupled joints.'])
add(2,4,'Relative-angle forward kinematics','A planar 2R arm has L₁ = L₂ = 2 m, first-link angle θ₁ = 0° from +x, and relative elbow angle θ₂ = 90°. What is its tip position?',['(2, 2) m.','(4, 0) m.','(0, 4) m.','(2, −2) m.'],['The first link contributes (2,0) and the second contributes (0,2).','This treats the elbow angle as zero.','This rotates both links to 90° rather than only the second absolute direction.','This uses −90° for the elbow rotation.'],'The second link’s absolute direction is θ₁+θ₂, giving the tip (2,2) m.',typ='numerical',kinds={5:'equation',6:'derivation'},steps=['Second-link absolute angle = 0° + 90° = 90°.','x = 2 cos 0° + 2 cos 90° = 2 m; y = 2 sin 0° + 2 sin 90° = 2 m.'],formulas=[formula('x=L₁ cosθ₁+L₂ cos(θ₁+θ₂); y=L₁ sinθ₁+L₂ sin(θ₁+θ₂)',{'x,y':'tip coordinates in base plane','L₁,L₂':'link lengths','θ₁':'first-link angle from +x','θ₂':'relative elbow angle'},{'x,y,L₁,L₂':'m','θ₁,θ₂':'angles, evaluated in degrees here'},['Planar rigid 2R links and counterclockwise positive angles.'])])
add(2,5,'Scope of an inverse-kinematic bound','The assignment reports at most eight IK solutions for its discussed six-DOF geometry and lists a₃ = a₅ = 0. How should that statement be used when assessing a different six-DOF robot?',['Treat the count as geometry-specific; the two zero parameters alone do not prove the same bound for every architecture.','Infer exactly eight reachable configurations at every target from the six-DOF count alone.','Infer a unique solution at every target because two listed DH lengths vanish.','Infer that every target has at least eight real solutions whenever those two lengths vanish.'],['IK multiplicity depends on the complete architecture, target and constraints, not just two parameter values.','A maximum count is not an existence or exact-count claim for every target.','Zeroing two lengths does not by itself prove unique inverse kinematics.','A maximum cannot be read as a universal minimum or reachability guarantee.'],'The printed bound should not be generalized beyond its specified geometry from two zero DH parameters alone.',assumptions=['The source’s model-specific statement is retained, but no complete alternate robot geometry is supplied.'])
add(2,6,'Qualified two-link inverse kinematics','Repair the original missing third-link data by explicitly using a planar 2R arm with L₁ = 3 m, L₂ = 2 m and target (4,0) m. With relative elbow angle θ₂ in [−180°,180°], which result follows?',['cosθ₂ = 0.25, so θ₂ ≈ ±75.52°.','θ₂ = 0.25°, because the cosine-law ratio is already the angle in degrees.','cosθ₂ = −0.25, so θ₂ ≈ ±104.48°.','θ₂ = 0°, because the target lies on the base x-axis.'],['The cosine law yields 0.25; taking both inverse-cosine branches gives the two elbow configurations.','The dimensionless cosine value must be inverted to obtain an angle.','This reverses the numerator sign in the cosine-law equation.','The base target direction does not force the relative elbow angle to zero.'],'For the explicitly supplied 2R model, the source’s 0.25 is a cosine, not the angle. Both elbow branches are possible before joint limits.',typ='numerical',difficulty='medium',kinds={6:'derivation'},assumptions=['This is a declared two-link adaptation, not a solution to an unspecified three-link arm. No joint limits or obstacles.'],steps=['r²=4²+0²=16 m².','cosθ₂=(16−9−4)/(2·3·2)=3/12=0.25.','θ₂=±acos(0.25)≈±75.52°.'],formulas=[formula('cosθ₂=(x²+y²−L₁²−L₂²)/(2L₁L₂)',{'x,y':'target coordinates','L₁,L₂':'positive link lengths','θ₂':'relative elbow angle'},{'x,y,L₁,L₂':'m','cosθ₂':'dimensionless','θ₂':'angle'},['Planar 2R model; reachable target; inverse-cosine branch choices considered.'])],conflict='The original calls the arm three-link but supplies only two lengths and asks for θ₂ while the keyed 0.25 is cosθ₂ from a 2R calculation.')
add(2,7,'Jacobian rank and directions','For ẋ = J q̇ with J = [[1,2],[2,4]], which pair correctly identifies a nonzero null joint velocity and the reachable output-velocity direction?',['q̇ = (−2,1)ᵀ is null; outputs lie along (1,2)ᵀ.','q̇ = (1,2)ᵀ is null; outputs lie along (−2,1)ᵀ.','q̇ = (2,1)ᵀ is null; outputs span the whole plane.','q̇ = (−1,2)ᵀ is null; only zero output is reachable.'],['Multiplication gives J(−2,1)ᵀ=0, while both columns are multiples of (1,2)ᵀ.','The proposed null vector produces (5,10)ᵀ, and the reachable direction is exchanged.','The proposed vector produces (4,8)ᵀ and the rank is one, not two.','The proposed vector produces (3,6)ᵀ; the nonzero matrix does permit nonzero output.'],'The matrix has rank one: one joint-velocity combination is invisible and the output spans a line.',typ='numerical',difficulty='medium',kinds={6:'equation',7:'derivation'},assumptions=['Coordinates and Jacobian entries use mutually compatible normalized units.'],steps=['The second column is twice the first, so rank is one.','Set q̇₁+2q̇₂=0, for example (−2,1).','All outputs equal (q̇₁+2q̇₂)(1,2)ᵀ.'],formulas=[formula('ẋ=Jq̇=(q̇₁+2q̇₂)(1,2)ᵀ',{'ẋ':'two-component output velocity','q̇':'two-component joint velocity','J':'given 2 by 2 Jacobian','q̇₁,q̇₂':'joint velocity components'},{'ẋ,q̇':'compatible normalized rates','J':'normalized mapping'},['The supplied constant Jacobian is evaluated at the configuration of interest.'])])
add(2,8,'Singularity location','Which distinction matches the source’s classification of interior and boundary singularities?',['An interior singularity lies inside the workspace, whereas a boundary singularity lies on its reachable boundary.','An interior singularity is defined by low joint speed, whereas a boundary singularity is defined by high joint speed.','An interior singularity is any collision, whereas a boundary singularity is any joint-limit warning.','An interior singularity requires zero link lengths, whereas a boundary singularity requires a fixed base.'],['This is the source’s spatial classification of singular configurations.','Speed does not define the spatial category.','Collision and joint-limit events are not themselves definitions of Jacobian singularities.','These structural properties do not define the two categories.'],'The categories describe where singular configurations occur relative to the workspace; both involve loss of relevant instantaneous mobility.')
add(2,9,'Force and lever-arm frames','For a single planar joint, define the tip lever arm as r = (0.30,0) m and applied force as F = (10,5) N, BOTH expressed in the same local frame. What is the out-of-plane torque r×F?',['+1.50 N·m.','+3.00 N·m.','−1.50 N·m.','0 N·m.'],['τ_z=r_xF_y−r_yF_x=0.30·5=1.50 N·m.','This incorrectly uses the force parallel to the lever arm.','This reverses the stated cross-product order.','Only the parallel force component contributes zero; the perpendicular component is nonzero.'],'The torque is +1.50 N·m only under the explicitly matched local lever-arm and force frame. A differently expressed force must first be transformed.',typ='numerical',kinds={7:'equation'},assumptions=['Added complete lever arm and force-frame convention; +z follows the right-hand rule from +x toward +y.'],steps=['Use the same frame for r and F.','Compute r_xF_y−r_yF_x=0.30·5−0·10=1.50 N·m.'],formulas=[formula('τ_z=r_xF_y−r_yF_x',{'τ_z':'out-of-plane moment','r_x,r_y':'lever-arm components from joint to force application point','F_x,F_y':'force components in the same frame'},{'τ_z':'N·m','r_x,r_y':'m','F_x,F_y':'N'},['Planar force and lever arm in one right-handed frame.'])],conflict='The original has missing length/angle symbols and no force-frame convention. The printed 1.5 N·m is reproduced only after explicitly supplying the compatible local lever arm.')
add(2,10,'Static force-model assumptions','For the simplified static link-force balance discussed in the assignment, which assumption set is consistent with neglecting link weight and inertial forces?',['Link gravitational and inertial forces are omitted while external forces and joint reactions are balanced.','The manipulator is in free fall, so every external force and reaction is omitted.','Only velocity-dependent effects are omitted, while arbitrary acceleration forces are retained as static terms.','All joint reactions are set to zero while a nonzero applied end force is retained.'],['This states the intended idealized force-balance model.','Free fall is not the definition of the stated static balance.','Retaining arbitrary acceleration terms is not a static inertial-force neglect.','A nonzero end load generally requires balancing reactions.'],'The highlighted choice describes the intended simplification. The contradictory printed letter is retained only in the immutable original, not silently accepted.',conflict='On physical page 7, Week 2 Q10 highlights option B (neglecting gravity/inertial forces) but prints Answer D (free fall).')
# Week 3: dynamics, axes, energy and matrix dimensions.
add(3,1,'Parallel-axis inertia','A rigid body has mass 2 kg and centroidal I_C,zz = 0.10 kg·m². The parallel z-axis through A is displaced from the COM by (x_c,y_c,z_c) = (0.30,0.40,0.50) m. What is I_A,zz?',['0.60 kg·m².','1.10 kg·m².','0.10 kg·m².','0.42 kg·m².'],['Only the perpendicular squared distance contributes: 0.10+2(0.30²+0.40²)=0.60.','This incorrectly includes displacement along the parallel z-axis.','Translation away from the axis changes the moment; retaining the centroidal value omits the correction.','This uses only y_c² and drops x_c².'],'Use distance perpendicular to the parallel axis, not the full three-dimensional displacement.',typ='numerical',kinds={8:'equation'},assumptions=['Added numeric values; axes have the same orientation, and I_C,zz is about the COM axis.'],steps=['d_perp² = 0.30² + 0.40² = 0.25 m².','I_A,zz = 0.10 + 2·0.25 = 0.60 kg·m².'],formulas=[formula('I_A,zz=I_C,zz+m(x_c²+y_c²)',{'I_A,zz':'moment about the translated z-axis through A','I_C,zz':'moment about the parallel COM z-axis','m':'body mass','x_c,y_c,z_c':'COM displacement components from A in the shared axis orientation'},{'I_A,zz,I_C,zz':'kg·m²','m':'kg','x_c,y_c,z_c':'m'},['Parallel axes; z_c is along the rotation axis and does not enter the correction.'])])
add(3,2,'Cylinder axis from the figure','Using the assignment figure’s central longitudinal rotation axis, a uniform solid cylinder has mass 6 kg, radius 0.20 m and length 0.40 m. What is its axial moment of inertia?',['0.12 kg·m².','0.24 kg·m².','0.14 kg·m².','0.06 kg·m².'],['For this solid-cylinder axis, I=½mR²=0.12.','mR² is the thin cylindrical shell result, not the uniform solid cylinder.','This is the stated cylinder’s transverse COM inertia m(3R²+L²)/12, about a different axis.','This uses ¼mR² and omits the relevant axial factor.'],'The pictured axis passes lengthwise through the center, so use ½mR², not the transverse-axis formula.',typ='numerical',kinds={8:'figure',9:'equation'},assumptions=['Added mass and dimensions; homogeneous solid cylinder, not a hollow shell.'],steps=['Identify the longitudinal COM axis in the source diagram.','I = 0.5·6·0.20² = 0.12 kg·m².'],formulas=[formula('I_axial=½mR²',{'I_axial':'moment about the central longitudinal axis','m':'cylinder mass','R':'cylinder radius'},{'I_axial':'kg·m²','m':'kg','R':'m'},['Uniform solid cylinder. Length does not enter this axial moment.'])])
add(3,3,'Angular momentum and Euler moment','In N = I_C α + ω×(I_C ω), what does I_C ω represent when I_C and ω are expressed in the same body frame about the COM?',['Angular momentum about the COM, expressed in that frame.','Angular acceleration about the COM.','The resultant moment N, without the other terms.','Linear momentum of the COM.'],['Inertia times angular velocity is angular momentum about the chosen point.','Angular acceleration is α, not inertia times angular velocity.','The moment includes the acceleration and cross-product contributions.','Linear momentum is mass times COM translational velocity, not I_Cω.'],'I_Cω is COM angular momentum; the cross product accounts for its rotating-frame transport in the body-frame Euler equation.',kinds={9:'equation'},formulas=[formula('H_C=I_Cω; N=I_Cα+ω×H_C',{'H_C':'angular momentum about COM','I_C':'constant body-frame COM inertia tensor','ω':'body angular velocity','α':'angular acceleration','N':'net applied moment about COM'},{'H_C':'kg·m²/s','I_C':'kg·m²','ω':'rad/s','α':'rad/s²','N':'N·m'},['All vector components in the same body-fixed frame; rigid body and moment about COM.'])])
add(3,4,'Net force magnitude','A body of mass 4 kg has COM acceleration (3,0,4) m/s². What is the magnitude of its NET external force?',['20 N.','28 N.','16 N.','100 N.'],['The acceleration norm is 5 m/s², so the force norm is 4·5=20 N.','This adds component magnitudes 12+16 instead of taking a Euclidean norm.','This retains only the z component of the force.','This uses m(a_x²+a_z²) without taking the square root.'],'The net force vector is (12,0,16) N and its magnitude is 20 N; gravity is not added again to a net-force calculation.',typ='numerical',kinds={9:'equation'},steps=['F_net = m a = (12,0,16) N.','||F_net|| = √(12²+16²) = 20 N.'],formulas=[formula('F_net=ma; ||F_net||=m√(a_x²+a_y²+a_z²)',{'F_net':'sum of all external forces','m':'mass','a_x,a_y,a_z':'COM acceleration components','||F_net||':'Euclidean magnitude'},{'F_net,||F_net||':'N','m':'kg','a_x,a_y,a_z':'m/s²'},['Inertial frame; positive mass; acceleration already results from all forces.'])])
add(3,5,'Gravity in recursive initialization','The assignment figure has +Y₀ upward. To account for physical gravity g_phys = −g Ŷ₀ by fictitious base acceleration in the stated Newton–Euler recursion, which initialization is appropriate?',['v̇₀ = +g Ŷ₀.','v̇₀ = −g Ŷ₀.','v̇₀ = 0 while also omitting gravity everywhere else.','v̇₀ = +g X̂₀.'],['The recursion injects the negative of the physical gravitational acceleration.','This uses gravity’s physical direction instead of the fictitious opposite acceleration in this convention.','Omitting both terms removes the gravity contribution.','This changes the axis contrary to the depicted vertical direction.'],'With physical gravity downward along −Y₀, the compensating recursion initialization is upward +g Ŷ₀.',typ='diagram',kinds={10:'figure'},formulas=[formula('v̇₀ = −g_phys = +g Ŷ₀',{'v̇₀':'fictitious base translational acceleration used by the recursion','g_phys':'physical gravitational acceleration vector','g':'positive gravity magnitude','Ŷ₀':'upward unit vector of the base frame'},{'v̇₀,g_phys,g':'m/s²','Ŷ₀':'dimensionless'},['The source convention embeds gravity through base acceleration instead of adding body weight separately.'])])
add(3,6,'Terminal wrench boundary','In the shown two-link Newton–Euler recursion, the boundary values f₃ = 0 and n₃ = 0 are used. What do these values state?',['No external tip force or moment is transmitted at that terminal boundary.','Every internal joint force and torque must be zero.','Both links must have zero mass and inertia.','All joint accelerations must be zero.'],['The boundary removes an externally applied terminal wrench, not the links’ dynamic loads.','Internal reactions can still balance inertia and gravity.','Zero terminal load does not remove link mass or inertia.','A robot can accelerate with no external tip contact wrench.'],'A zero terminal wrench is a load boundary condition, not a statement of static or massless motion.',kinds={10:'figure',11:'statement'},assumptions=['The index 3 is the source’s terminal frame after its two modeled links.'])
add(3,7,'Configuration and velocity terms','For τ = M(q)q̈ + V(q,q̇) + G(q), compare two trials at the same q and q̈ but different q̇, with unchanged gravity. Which term can change solely because the joint rates change?',['V(q,q̇), while M(q) and G(q) remain evaluated at the same configuration.','G(q), while V(q,q̇) must remain unchanged.','M(q), solely because the rate changes at fixed q.','All three terms must change by the same multiplicative factor.'],['Velocity-product terms depend on joint rates; inertia and gravity retain their configuration arguments.','Gravity at a fixed configuration and fixed field is not a joint-rate term.','In this stated model M depends on q, which is unchanged.','No common scaling law follows from changing rates.'],'The Coriolis/centrifugal vector may change with q̇ even when the configuration-dependent inertia and gravity quantities do not.',typ='scenario',kinds={11:'equation',12:'statement'},assumptions=['Standard rigid manipulator model shown, with fixed parameters and gravity; “can change” does not mean every possible rate change produces a different V.'],formulas=[formula('τ=M(q)q̈+V(q,q̇)+G(q)',{'τ':'joint generalized force vector','q,q̇,q̈':'joint coordinates, rates and accelerations','M':'joint inertia matrix','V':'Coriolis/centrifugal generalized-force vector','G':'gravity generalized-force vector'},{'q':'rad for revolute joints, m for prismatic joints','q̇,q̈':'corresponding units per s and per s²','τ,V,G':'N·m for revolute components, N for prismatic components','M':'compatible inertia mapping units'},['Rigid links; fixed parameters; all terms in the same generalized coordinates.'])])
add(3,8,'COM kinetic-energy decomposition','An added rigid-body example has mass 2 kg, COM velocity (3,4,0) m/s, angular velocity (0,0,2) rad/s and COM I_zz = 0.50 kg·m² in the same axes. What is its total kinetic energy?',['26 J.','25 J.','27 J.','51 J.'],['Translational energy is 25 J and rotational energy is 1 J.','This drops the rotational contribution.','This omits the factor ½ in the rotational contribution.','This omits the factor ½ in translational energy, giving 50+1.'],'Use translation of the COM plus rotation about the COM to obtain 25+1=26 J, without double counting motion.',typ='numerical',difficulty='medium',kinds={12:'equation'},assumptions=['Added numerical values; angular velocity has only a z component, so other inertia entries do not contribute.'],steps=['K_trans = ½·2·(3²+4²) = 25 J.','K_rot = ½·0.50·2² = 1 J.','K = 26 J.'],formulas=[formula('K=½m v_Cᵀv_C+½ωᵀI_Cω',{'K':'total kinetic energy','m':'mass','v_C':'COM velocity in inertial coordinates','ω':'angular velocity','I_C':'inertia about COM in the same axes as ω'},{'K':'J','m':'kg','v_C':'m/s','ω':'rad/s','I_C':'kg·m²'},['Rigid body; translational speed evaluated in an inertial frame.'])])
add(3,9,'Two-point-mass manipulator inertia','Use the assignment diagram: massless planar links of lengths l₁,l₂, point mass m₁ at the elbow and m₂ at the tip, with relative elbow angle q₂. For m₁ = 2 kg, m₂ = 3 kg, l₁ = 1 m, l₂ = 2 m and q₂ = 60°, derive M from K = ½ q̇ᵀM q̇. Which matrix is obtained?',['[[23,15],[15,12]] kg·m².','[[23,12],[12,12]] kg·m².','[[17,15],[15,12]] kg·m².','[[12,15],[15,23]] kg·m².'],['The tip speed contributes both squared rates and their coupling, producing M11=23, M12=M21=15 and M22=12.','This omits m₂l₁l₂cos q₂ from the off-diagonal coupling.','This omits the 2m₂l₁l₂cos q₂ contribution in M11.','This swaps the diagonal roles of base and elbow rates.'],'Collect the q̇₁², 2q̇₁q̇₂ and q̇₂² coefficients of the complete two-mass kinetic energy; the symmetric matrix is [[23,15],[15,12]].',typ='derivation',difficulty='medium',kinds={12:'figure',13:'equation'},locs={12:'Week 3 item 9, two-link point-mass geometry and relative-angle labels',13:'Week 3 item 9, candidate inertia matrices and explanation'},assumptions=['Added parameter values; both generalized coordinates are revolute angles, rods have zero mass, and no distributed-link inertia is added.'],steps=['v₁²=l₁² q̇₁².','v₂²=l₁²q̇₁²+l₂²(q̇₁+q̇₂)²+2l₁l₂ cos q₂·q̇₁(q̇₁+q̇₂).','Expand K=½m₁v₁²+½m₂v₂² and collect the quadratic coefficients.','M11=(m₁+m₂)l₁²+m₂l₂²+2m₂l₁l₂cos q₂=23; M12=M21=m₂l₂²+m₂l₁l₂cos q₂=15; M22=m₂l₂²=12.'],formulas=[formula('M11=(m₁+m₂)l₁²+m₂l₂²+2m₂l₁l₂cos q₂; M12=M21=m₂l₂²+m₂l₁l₂cos q₂; M22=m₂l₂²',{'Mij':'row i, column j element of the 2 by 2 generalized inertia matrix','m₁,m₂':'point masses at elbow and tip','l₁,l₂':'link lengths','q₂':'relative elbow angle','q̇₁,q̇₂':'base and relative elbow angular rates','K':'total kinetic energy'},{'Mij':'kg·m²','m₁,m₂':'kg','l₁,l₂':'m','q₂':'angle','q̇₁,q̇₂':'rad/s','K':'J'},['Massless planar 2R rods; point masses only at the displayed locations; K=½q̇ᵀMq̇.'])])
add(3,10,'Mixed velocity-product dimension','The source groups distinct mixed products q̇_i q̇_j with i<j into one vector, separate from squared rates. For four joints and four generalized-force outputs, what is the size of its coefficient matrix B?',['4×6.','4×4.','4×12.','6×4.'],['There are 4·3/2=6 unordered distinct pairs and four output rows.','Four is the number of squared-rate terms, not distinct mixed pairs.','Twelve double-counts each pair as (i,j) and (j,i).','This transposes the input-product and output dimensions.'],'Four output components times six distinct mixed-rate products gives a 4×6 matrix.',typ='numerical',kinds={13:'equation',14:'derivation'},steps=['Count unordered pairs: (1,2),(1,3),(1,4),(2,3),(2,4),(3,4).','A four-component output equals B times this six-component product vector, so B is 4×6.'],formulas=[formula('B ∈ R^[n × n(n−1)/2]',{'B':'coefficient matrix multiplying the vector of distinct mixed joint-rate products','n':'number of joint coordinates and generalized-force outputs','i,j':'joint indices with i<j'},{'n,i,j':'dimensionless','B':'force/rate-product-compatible units'},['Squared-rate terms are collected separately; unordered mixed pairs counted once.'])])
# Week 4: trajectory boundary conditions, workspace and mechanisms.
add(4,1,'Quintic endpoint constraints','A single polynomial segment must independently satisfy prescribed position, velocity AND acceleration at both endpoints. What is the lowest generic polynomial degree with enough coefficients?',['Five, providing six coefficients.','Three, providing four coefficients.','Four, providing five coefficients.','Two, providing three coefficients.'],['Six independent scalar constraints generically require six coefficients, supplied by a quintic.','A cubic has only four coefficients and cannot generally satisfy six independent conditions.','A quartic is one coefficient short for six generic independent constraints.','A quadratic supplies only three coefficients.'],'The quintic requirement follows from six independent endpoint conditions, not from claiming that a lower-degree polynomial is internally nonsmooth.',assumptions=['Distinct endpoint times; arbitrary independent scalar position/velocity/acceleration boundary data. Special compatible data may admit a lower-degree solution.'])
add(4,2,'Cubic rest-to-rest segment','For an added scalar rest-to-rest motion q(0)=0, q̇(0)=0, q(2)=1 rad and q̇(2)=0, use q(t)=a₂t²+a₃t³ with t in seconds. Which coefficient pair satisfies all four endpoint conditions?',['a₂=0.75 rad/s², a₃=−0.25 rad/s³.','a₂=0.50 rad/s², a₃=−0.125 rad/s³.','a₂=1.50 rad/s², a₃=−0.50 rad/s³.','a₂=0.75 rad/s², a₃=+0.25 rad/s³.'],['4a₂+8a₃=1 and 4a₂+12a₃=0 yield the stated pair.','This reaches 1 rad but its final velocity is 0.5 rad/s, not zero.','This retains zero final velocity but reaches 2 rad instead of 1.','The positive cubic term violates both final constraints.'],'A cubic can match endpoint positions and velocities; these four conditions do not also impose zero endpoint acceleration.',typ='numerical',difficulty='medium',kinds={15:'statement'},assumptions=['Added boundary-value exercise based on the source’s four cubic constraints; t=0 at the segment start.'],steps=['q(2)=4a₂+8a₃=1.','q̇(2)=4a₂+12a₃=0.','Subtract to get a₃=−0.25, then a₂=0.75.'],formulas=[formula('q(t)=a₂t²+a₃t³; q̇(t)=2a₂t+3a₃t²',{'q':'joint displacement','t':'time from segment start','a₂,a₃':'polynomial coefficients','q̇':'joint angular rate'},{'q':'rad','t':'s','q̇':'rad/s','a₂':'rad/s²','a₃':'rad/s³'},['Zero initial position and rate remove constant and linear coefficients.'])])
add(4,3,'LSPB continuity qualification','In an added ordinary parabolic-to-linear blend, q̇(t)=t m/s for 0<t<1 s and q̇(t)=1 m/s for 1<t<3 s, where the first expression uses acceleration 1 m/s². What happens at t=1 s?',['Velocity is continuous, but its acceleration jumps from 1 m/s² to 0.','Both velocity and acceleration are continuous.','Velocity jumps from 0 to 1 m/s, while acceleration stays continuous.','Acceleration is continuous only because the cruise velocity is nonzero.'],['The one-sided velocities agree at 1 m/s, while their time derivatives differ.','Equal velocity limits do not make unequal acceleration limits continuous.','The left velocity tends to 1 m/s, not zero.','Cruise speed does not change the zero derivative of constant velocity.'],'Ordinary LSPB provides continuous velocity at the blend boundary but not continuous acceleration; the printed acceleration-continuity claim is not generally correct.',typ='numerical',difficulty='medium',kinds={15:'statement'},assumptions=['Added explicit piecewise velocity model; inspect one-sided limits at the transition. No smoothing of the acceleration switch is added.'],steps=['lim(t→1−) q̇ = 1 m/s = lim(t→1+) q̇.','The left derivative is 1 m/s²; the right derivative is 0.','Acceleration has a jump, even though velocity is continuous.'],formulas=[formula('q̈(t)=a on the parabolic blend; q̈(t)=0 on the constant-velocity segment',{'q̈':'acceleration','q̇':'velocity','t':'time','a':'constant blend acceleration'},{'q̈,a':'m/s²','q̇':'m/s','t':'s'},['Ordinary unsmoothed LSPB with a nonzero blend acceleration.'])],conflict='Week 4 Q3 states that LSPB has both continuous velocity and acceleration; ordinary piecewise parabolic/linear blending has acceleration jumps at its switches.')
add(4,4,'Qualified orientation travel','Constrain motion to rotation about the SAME fixed axis. From 10° to an equivalent target orientation represented by 350°, either −20° or +340° reaches the target. With no joint limits, which path minimizes angular travel?',['−20°.','+340°.','+180°.','−350°.'],['The equivalent displacement of magnitude 20° is shorter than 340°.','This reaches the target but takes the long way around the same axis.','A half turn does not reach the specified target orientation.','This ends at −340°≡20°, not the target 350°.'],'For the explicitly fixed axis, compare equivalent angle displacements modulo 360°. This does not justify subtracting arbitrary 3D rotation vectors as a universal orientation metric.',typ='numerical',assumptions=['Added fixed-axis example, no joint limits or collision constraints; orientations compared modulo a full turn.'],steps=['Raw displacement is 350°−10°=340°.','Subtract 360° to obtain the equivalent −20° displacement.','Choose the smaller magnitude, 20°.'],formulas=[formula('Δθ=θ_target−θ_start+360°k',{'Δθ':'equivalent signed same-axis angular displacement','θ_target,θ_start':'target and starting angles about the same fixed axis','k':'integer branch index'},{'Δθ,θ_target,θ_start':'degrees','k':'dimensionless integer'},['Choose a feasible branch minimizing |Δθ|; this scalar formula is not a general rotation-vector distance.'])])
add(4,5,'Repeatability versus accuracy','A robot repeatedly reaches positions tightly clustered 4 mm away from the commanded target. Which assessment follows?',['Good repeatability but a systematic accuracy error.','Poor repeatability but exact accuracy.','Good accuracy because the spread is small, irrespective of the offset.','Neither repeatability nor accuracy can be discussed unless speed is zero for the entire motion.'],['Small spread measures repeatability; the offset from target is an accuracy error.','The observations show the opposite combination.','A tight cluster can still be biased away from the target.','Endpoint statistics can assess both without requiring the entire motion to be stationary.'],'Repeatability concerns consistency across repetitions, whereas accuracy concerns closeness to the desired target.',typ='scenario',assumptions=['Added measured endpoint pattern; the same target and operating conditions are used repeatedly.'])
add(4,6,'Annular two-link workspace','An obstacle-free planar 2R arm has lengths 5 m and 4 m, with unrestricted revolute joints. Which target radius is unreachable even though it is less than the maximum reach?',['0.5 m.','1 m.','5 m.','9 m.'],['The inner radius is |5−4|=1 m, so 0.5 m is inside the unreachable hole.','The fully folded configuration reaches radius 1 m.','The radius lies between 1 and 9 m.','The fully extended configuration reaches the outer boundary at 9 m.'],'The reachable radial interval is 1≤r≤9 m; maximum reach alone is not sufficient to establish reachability.',typ='numerical',kinds={16:'equation'},steps=['r_min=|5−4|=1 m.','r_max=5+4=9 m.','Only 0.5 m lies outside that interval.'],formulas=[formula('|L₁−L₂|≤r≤L₁+L₂',{'L₁,L₂':'positive planar link lengths','r':'distance from base to tip'},{'L₁,L₂,r':'m'},['Unrestricted 2R joint angles, no obstacles or self-collision restrictions.'])])
add(4,7,'Redundancy and local self-motion','A seven-joint robot performs a six-component pose task at a regular configuration where its 6×7 Jacobian has rank six. What is the local joint-velocity null-space dimension?',['One, permitting a local task-preserving joint-velocity direction.','Zero, because the task has six components.','Six, one for every task component.','Seven, because the robot has seven joints.'],['Rank-nullity gives 7−6=1.','Full row rank still leaves one more joint variable than independent task constraints.','The rank is six, not the nullity.','All seven directions would be null only for a zero-rank task Jacobian.'],'One local redundant direction is available; finite motions must still respect joint limits, collisions and changing singularities.',typ='numerical',assumptions=['Added full-rank local condition; seven independent joint coordinates and a six-dimensional differential pose task.'],steps=['Nullity = number of columns − rank = 7−6 = 1.'],formulas=[formula('dim ker J=n−rank J',{'J':'task Jacobian','n':'number of independent joint-rate coordinates','ker J':'joint rates producing zero instantaneous task velocity'},{'n,rank J,dim ker J':'dimensionless counts'},['Linear velocity map at a fixed configuration.'])])
add(4,8,'Compliance and rigid kinematics','Joint encoders report the intended angles accurately, but a long link bends under a payload and the tool misses its predicted point. Which correction addresses the missing effect most directly?',['Include load-dependent elastic deflection or compensate using measured tool deformation.','Repeat the same rigid forward-kinematic calculation with unchanged link geometry.','Treat repeatable encoder readings as proof that the tool position must be exact.','Change the displayed coordinate origin without modeling or measuring the deflection.'],['The discrepancy arises from geometry changing under load, which the rigid model omits.','Recomputing the same rigid model does not add the missing compliance.','Accurate joint readings do not measure all structural bending.','A coordinate relabeling cannot remove physical deformation.'],'Rigid forward kinematics can be inaccurate under compliance even when joint-angle measurements are accurate.',typ='scenario')
add(4,9,'SCARA directional compliance','For the source’s SCARA assembly role, which directional behavior is intended to accommodate small lateral insertion errors while supporting vertical loads?',['Relatively compliant horizontal motion with comparatively stiff vertical support.','Relatively compliant vertical support with comparatively stiff horizontal motion.','Equal low stiffness in every direction regardless of assembly load.','High stiffness in every direction with no lateral accommodation.'],['The source contrasts horizontal compliance with vertical rigidity for assembly.','This reverses the intended directional behavior.','Isotropic low stiffness would not supply the described vertical support.','Removing lateral compliance removes the stated accommodation mechanism.'],'The source’s design intent is selective compliance, not infinite vertical stiffness or unrestricted lateral motion.',assumptions=['Relative directional stiffness of the described SCARA design, not a universal numerical stiffness specification.'])
add(4,10,'SCARA planar singularity branches','For the SCARA planar positioning subchain with positive link lengths l₁,l₂ and determinant proportional to l₁l₂ sinθ₂, which relative elbow angles are singular modulo 360°?',['0° and 180°.','90° and 270°.','45° and 225°.','Only 0°, but not 180°.'],['sinθ₂ vanishes for both extended and folded collinear configurations.','These angles have sine ±1, not zero.','These angles have nonzero sine.','The folded branch also has zero sine.'],'Both collinear branches are singular. The actual assignment explanation correctly prints sinθ₂=0; the earlier handoff misread is not a source conflict.',kinds={18:'equation'},formulas=[formula('det J_planar=l₁l₂ sinθ₂',{'J_planar':'2 by 2 planar translational Jacobian for the two revolute links','l₁,l₂':'positive link lengths','θ₂':'relative elbow angle'},{'l₁,l₂':'m','θ₂':'angle','det J_planar':'m² under radian-angle coordinates'},['The planar 2R subchain, not every axis of the full SCARA mechanism.'])])
# Week 5: closed-loop dynamics, units and power duality.
add(5,1,'Critical second-order dynamics','For the unforced mass–spring–damper model m ẍ+b ẋ+kx=0 with m=1 kg, b=6 N·s/m and k=9 N/m, which pole/damping description is correct?',['A repeated pole at −3 s⁻¹; critically damped.','Poles at −3±3i s⁻¹; underdamped.','Two distinct negative real poles; overdamped.','A repeated pole at +3 s⁻¹; unstable.'],['The characteristic polynomial is s²+6s+9=(s+3)².','The discriminant is zero, so there is no imaginary pair.','Critical damping gives coincident rather than distinct real poles.','The positive damping coefficient gives a negative repeated pole here.'],'The zero discriminant and repeated negative pole establish critical damping.',typ='numerical',kinds={19:'equation'},steps=['b²−4mk=36−36=0.','s=−b/(2m)=−3 s⁻¹.'],formulas=[formula('ms²+bs+k=0; ζ=b/(2√(mk)); ω_n=√(k/m)',{'m':'mass','b':'viscous damping coefficient','k':'spring stiffness','s':'characteristic growth/decay rate','ζ':'damping ratio','ω_n':'undamped natural angular frequency'},{'m':'kg','b':'N·s/m','k':'N/m','s':'s⁻¹','ζ':'dimensionless','ω_n':'rad/s'},['Linear scalar model with m,k>0 and no applied force.'])])
add(5,2,'Feedback stiffness and damping','For m ẍ+b ẋ+kx=f with m=4 kg, b=1 N·s/m and k=1 N/m, choose f=−k_p x−k_v ẋ. Require total stiffness 16 N/m and critical damping. Which gains meet both conditions?',['k_p=15 N/m and k_v=15 N·s/m.','k_p=16 N/m and k_v=16 N·s/m.','k_p=15 N/m and k_v=16 N·s/m.','k_p=15 N/m and k_v=7 N·s/m.'],['k+k_p=16 and b+k_v=2√(4·16)=16, giving 15 for each appropriately dimensioned gain.','This fails to subtract the existing stiffness and damping.','The stiffness is correct, but 16 as the added damping ignores the existing b=1.','This uses 2√16−1=7 and omits the mass in the damping requirement.'],'Design the total closed-loop coefficients first, then subtract the existing plant coefficients.',typ='numerical',difficulty='medium',kinds={19:'equation',20:'derivation'},steps=['k_p=16−1=15 N/m.','b_total=2√(m k_total)=2√64=16 N·s/m.','k_v=16−1=15 N·s/m.'],formulas=[formula('k_total=k+k_p; b_total=b+k_v; b_total=2√(m k_total)',{'m':'plant mass','k,b':'plant stiffness and viscous damping','k_p,k_v':'added proportional and velocity-feedback gains','k_total,b_total':'closed-loop stiffness and damping'},{'m':'kg','k,k_p,k_total':'N/m','b,k_v,b_total':'N·s/m'},['Negative position/velocity feedback, linear scalar plant, critical damping with positive total stiffness.'])])
add(5,3,'Back EMF versus terminal voltage','For the stated DC motor convention, which equation identifies rotational back EMF without confusing it with the complete terminal voltage balance?',['e_back=k_eω, while V=Ri+L di/dt+e_back.','e_back=Ri, while V=k_eω regardless of armature current.','e_back=L di/dt, while rotational speed affects only resistance.','e_back=V+Ri+L di/dt under the stated opposing-EMF convention.'],['Speed generates back EMF, while terminal voltage also supplies resistive and inductive drops.','Ri is the resistive drop, not the speed-generated EMF.','The inductive drop depends on current change, not solely rotational EMF.','Rearranging the stated balance gives e_back=V−Ri−L di/dt, not plus the drops.'],'The symbol for back EMF must be distinguished from terminal voltage; the source’s speed-proportional relation is not the entire loaded armature voltage.',kinds={20:'equation'},assumptions=['Motoring sign convention: back EMF opposes the applied terminal voltage; fixed field and compatible motor constants.'],formulas=[formula('e_back=k_eω; V=Ri+L di/dt+e_back',{'e_back':'rotational back electromotive force','k_e':'back-EMF constant','ω':'shaft angular velocity','V':'armature terminal voltage','R':'armature resistance','i':'armature current','L':'armature inductance','t':'time'},{'e_back,V':'V','k_e':'V·s/rad','ω':'rad/s','R':'Ω','i':'A','L':'H','t':'s'},['Fixed-field lumped armature model; consistent motoring polarities.'])])
add(5,4,'Resonance separation guideline','Using only the assignment’s guideline ω_res≥2ω_n, a structural resonance is at 80 rad/s. What is the largest permitted ω_n under this guideline, and what does passing it establish?',['40 rad/s; it passes this guideline but is not a complete stability proof.','160 rad/s; it passes because controller bandwidth should exceed resonance.','80 rad/s; equality of resonance and bandwidth provides the required factor of two.','40 rad/s; it guarantees stability for every unmodeled flexible mode and delay.'],['80≥2ω_n gives ω_n≤40, and the heuristic alone cannot cover every dynamical effect.','This reverses the required separation.','Equal frequencies do not meet the stated factor of two.','The numerical bound is right but the universal guarantee is unsupported.'],'The source’s factor-of-two separation is a design rule, not a substitute for full robustness and stability analysis.',typ='numerical',kinds={20:'equation'},steps=['Solve 80≥2ω_n to obtain ω_n≤40 rad/s.','Retain the bounded scope of the given design guideline.'],formulas=[formula('ω_res≥2ω_n',{'ω_res':'structural resonance angular frequency','ω_n':'chosen closed-loop natural angular frequency in the source guideline'},{'ω_res,ω_n':'rad/s'},['Use as the stated design heuristic, not a universal stability theorem.'])])
add(5,5,'Declared feedback linearization','For the added normalized plant ẍ+x³=u, assume the model is exact. Which control substitution yields ẍ=v so that a subsequent linear feedback design can choose v?',['u=x³+v.','u=−x³+v.','u=v, without compensation.','u=x³v.'],['Substitution cancels the plant’s x³ term and leaves ẍ=v.','This leaves ẍ=v−2x³ rather than canceling.','This leaves ẍ=v−x³.','This gives ẍ=x³(v−1), not a linear auxiliary-input relation.'],'Cancel the modeled nonlinearity with the matching sign; cancellation alone does not choose a stabilizing auxiliary feedback.',typ='scenario',difficulty='medium',assumptions=['Added dimensionless normalized example and exact-model assumption; v is a new auxiliary input, not an unspecified promise of stability.'],steps=['Rearrange ẍ=u−x³.','Set u=x³+v, producing ẍ=v.','Design v separately for the desired closed-loop behavior.'],formulas=[formula('ẍ+x³=u; u=x³+v ⇒ ẍ=v',{'x':'normalized scalar state','u':'normalized physical control input','v':'normalized auxiliary input','ẍ':'second derivative with respect to normalized time'},{'x,u,v,ẍ':'dimensionless normalized quantities'},['Added exact normalized model; no actuator saturation or model mismatch included.'])])
add(5,6,'Linear and cubic spring units','At x=2 m, compare f₁=k₁x with k₁=10 N/m and f₂=k₂x³ with k₂=10 N/m³. What is f₂/f₁?',['4.','2.','8.','1.'],['f₁=20 N and f₂=80 N, so the ratio is four.','This uses x instead of the x² dependence in the ratio for these numeric coefficients.','Eight is x³ numerically, not the ratio to the linear force.','Equal coefficient numerals with different units do not imply equal forces.'],'The nonlinear force is four times the linear one at the specified displacement; the coefficients have different physical units.',typ='numerical',kinds={21:'equation'},steps=['f₁=10·2=20 N.','f₂=10·2³=80 N.','f₂/f₁=80/20=4.'],formulas=[formula('f₁=k₁x; f₂=k₂x³; f₂/f₁=(k₂/k₁)x²',{'f₁,f₂':'linear and cubic spring force values','k₁':'linear stiffness coefficient','k₂':'cubic coefficient','x':'nonzero displacement'},{'f₁,f₂':'N','k₁':'N/m','k₂':'N/m³','x':'m','f₂/f₁':'dimensionless'},['Compare the stated same-sign scalar force laws at the same nonzero displacement.'])])
add(5,7,'Independent joint input decomposition','In the source’s input decomposition τ=αu+β, let u already contain the independently computed joint torque commands. Which α and β pass those commands through without model-based coupling compensation?',['α=I and β=0.','α=0 and β=0.','α=M(q) and β=V(q,q̇)+G(q).','α=I and β=−u.'],['The identity and zero offset give τ=u.','This gives zero applied torque rather than passing through a nonzero joint command.','This is an explicit model-based dynamic compensation map, not the requested absence of compensation.','This cancels the commanded torque to zero.'],'The source’s independent-joint convention uses identity input scaling and zero model-based offset.',kinds={21:'equation',22:'statement'},assumptions=['u has joint-torque units already, unlike an acceleration-level computed-torque auxiliary input. I is the joint-space identity.'],formulas=[formula('τ=αu+β; α=I, β=0 ⇒ τ=u',{'τ':'applied joint torque vector','u':'independent joint torque-command vector','α':'input scaling matrix','β':'additive torque vector','I':'joint-space identity matrix'},{'τ,u,β':'N·m for the revolute-joint convention','α,I':'dimensionless'},['The pass-through decomposition in this question; no model cancellation is claimed.'])])
add(5,8,'Critical error response','For ë+6ė+9e=0, add initial conditions e(0)=0.1 rad and ė(0)=0. Which pair gives the natural frequency/damping ratio AND the corresponding response?',['ω_n=3 rad/s, ζ=1; e(t)=(0.1+0.3t)e^(−3t) rad, with t in seconds.','ω_n=9 rad/s, ζ=1; e(t)=0.1e^(−9t) rad.','ω_n=3 rad/s, ζ=1; e(t)=0.1e^(−3t) rad.','ω_n=3 rad/s, ζ=0.5; e(t)=0.1cos(3t) rad.'],['Matching coefficients gives ω_n=3 and ζ=1; the repeated-root response needs the t term to make the initial rate zero.','The natural frequency is the square root of nine, not nine, and the response has a nonzero initial rate.','The damping classification is right, but the proposed response has initial rate −0.3 rad/s.','The damping ratio is one, and an undamped cosine does not satisfy the damped equation.'],'The critically damped repeated-root form is (A+Bt)e^(−3t); the initial conditions give A=0.1 rad and B=0.3 rad/s.',typ='numerical',difficulty='medium',kinds={22:'equation'},assumptions=['Added initial conditions; coefficient 6 has units s⁻¹ and 9 has units s⁻².'],steps=['Compare with ë+2ζω_n ė+ω_n²e=0: ω_n=3, ζ=1.','Set e=(A+Bt)e^(−3t); e(0)=A=0.1.','ė(0)=B−3A=0 gives B=0.3 rad/s.'],formulas=[formula('e(t)=(A+Bt)e^(−ω_n t); ζ=1',{'e':'joint position error','t':'time','A':'initial error','B':'repeated-root coefficient fixed by initial error rate','ω_n':'natural angular frequency','ζ':'damping ratio'},{'e,A':'rad','t':'s','B':'rad/s','ω_n':'rad/s','ζ':'dimensionless'},['Critical second-order homogeneous equation with repeated pole −ω_n; angular frequency enters the exponent as inverse time.'])])
add(5,9,'Joint versus Cartesian errors','A controller forms q_d−q, q̇_d−q̇ and q̈_d−q̈ for each joint. Which description matches these signals?',['Joint-space position, velocity and acceleration errors.','Cartesian tool position, velocity and acceleration errors by definition.','Joint-space force, power and energy errors.','Raw encoder values with no desired-trajectory reference.'],['Each signal compares desired and actual joint quantities of the same order.','Converting to Cartesian task errors requires kinematic relationships, not just relabeling joint differences.','The quantities have coordinate/rate/acceleration dimensions, not force/power/energy.','The desired quantities are explicitly subtracted, so these are reference errors.'],'The source’s controller signals are joint-space trajectory errors; this does not mean every practical controller must measure or use all three.',assumptions=['q_d and q are desired and measured joint coordinates in matching order and units; dots denote time derivatives.'])
add(5,10,'Jacobian transpose and power','For the added planar map v=Jq̇ with J=[[1,2],[0,1]] m/rad and force F=(3,4)ᵀ N in the matching task frame, what joint torque vector preserves Fᵀv=τᵀq̇?',['τ=(3,10)ᵀ N·m.','τ=(11,4)ᵀ N·m.','τ=(−5,4)ᵀ N·m.','τ=(3,−2)ᵀ N·m.'],['JᵀF=[[1,0],[2,1]](3,4)ᵀ=(3,10)ᵀ.','This computes JF rather than JᵀF.','This computes J⁻¹F, which is not the force dual map.','This computes J⁻ᵀF rather than JᵀF.'],'The transpose follows from virtual power, even when the Jacobian is not symmetric.',typ='numerical',difficulty='medium',kinds={23:'equation'},assumptions=['Added two-revolute-coordinate example; compatible task force/velocity frame and joint ordering.'],steps=['Fᵀv=FᵀJq̇=(JᵀF)ᵀq̇.','Thus τ=JᵀF.','Multiply to obtain (3,2·3+4)ᵀ=(3,10)ᵀ N·m.'],formulas=[formula('v=Jq̇; τ=JᵀF; Fᵀv=τᵀq̇',{'v':'planar endpoint velocity','J':'task Jacobian','q̇':'joint angular-rate vector','F':'force expressed in the matching task frame','τ':'joint torque vector'},{'v':'m/s','J':'m/rad','q̇':'rad/s','F':'N','τ':'N·m'},['Virtual-power-consistent signs; radians treated as dimensionless in energy units.'])])
# Week 6: data types, geometrical model scope, regression leaves and RL.
add(6,1,'Nearest-neighbour metric','A k-NN classifier uses Euclidean distance on two raw features, one measured in metres and one in millimetres. What should be checked before interpreting “nearest” as useful similarity?',['Whether feature scaling and the chosen metric reflect the task’s intended similarity.','Whether a numeric class label can be added to every test feature vector before measuring distance.','Whether the largest raw numeric feature should always dominate, regardless of its unit.','Whether increasing k makes all distance-unit choices equivalent.'],['Raw mixed-unit scales can dominate distance; metric and preprocessing choices matter.','Adding the unknown test label leaks target information and is not a legitimate similarity construction.','Numerical magnitude from unit choice need not reflect importance.','Changing neighbour count does not remove the scale dependence of the metric.'],'The source’s local-similarity idea is conditional on a suitable distance representation, not raw numerical closeness under arbitrary units.',typ='scenario',assumptions=['Added mixed-unit example; no claim that a particular scaling method is always optimal.'])
add(6,2,'Classification target meaning','A terrain model predicts codes 0,1,2 that denote sand, grass and rock rather than ordered measurements. Which task is this, and why?',['Classification, because the target is a categorical label despite its numeric encoding.','Regression, because any integer-coded output is a continuous quantity.','Regression, because three classes require fitting three numerical distances.','Unsupervised clustering, because the class names can be replaced by numbers.'],['Target meaning, not its storage type, distinguishes class prediction from numerical regression.','Integer representation does not turn category codes into a continuous measurement.','Class count does not require a distance-valued target.','Encoding labeled targets differently does not remove their supervision.'],'Numerical class codes remain categorical targets.',typ='scenario')
add(6,3,'Supervision versus clustering','Dataset A pairs terrain images with known terrain labels. Dataset B contains only images and is grouped by feature similarity without labels. Which pairing matches the source’s supervised/unsupervised distinction?',['A is supervised classification; B is unsupervised clustering.','A is unsupervised because images are complex; B is supervised because groups are produced.','Both are supervised because an algorithm processes the images.','Both are unsupervised because terrain labels are stored as text.'],['The known target labels supervise A; B forms groups without supplied targets.','Data complexity and outputting a group do not determine supervision.','Running an algorithm does not imply labeled supervision.','Label storage as text does not remove its supervisory role.'],'The defining distinction is whether target labels supervise fitting, not input complexity or label encoding.',typ='scenario')
add(6,4,'Plane and hyperplane overlap','For ŷ=b₀+b₁x₁+b₂x₂ plotted as a graph in (x₁,x₂,ŷ) space, which geometrical statement avoids the original overlapping choices “plane” and “hyperplane”?',['It is a two-dimensional affine plane in R³, and that plane is also a hyperplane.','It is a one-dimensional line in R³ for every pair of coefficients.','It is a three-dimensional volume because three coordinate names appear.','It is a plane only when it is not a hyperplane.'],['The graph has two free input coordinates and codimension one in R³, so both names apply.','A model with two independently variable inputs has a two-dimensional graph, even if some slopes vanish.','The output is constrained by the equation, so the graph does not fill a 3D volume.','A plane in R³ is a hyperplane; these labels are not exclusive.'],'The most specific description is a two-dimensional affine plane in R³; the generic hyperplane description is also true.',kinds={25:'statement'},assumptions=['Inputs vary independently over R²; graph of the fitted scalar linear model, not a thresholded decision region.'],formulas=[formula('ŷ=b₀+b₁x₁+b₂x₂',{'ŷ':'predicted scalar response','x₁,x₂':'two independent features','b₀':'intercept','b₁,b₂':'feature coefficients'},{'ŷ,b₀':'response units','x₁,x₂':'respective feature units','b₁,b₂':'response units per respective feature unit'},['Affine scalar regression with two free inputs.'])],conflict='Week 6 Q4 offers both a plane and a hyperplane as separate alternatives for the two-input regression graph; both are mathematically true in R³.')
add(6,5,'Estimator fitting versus inference','In the assignment’s scikit-learn-style linear-regression workflow, which call learns model parameters from labeled feature/target pairs X and y?',['model.fit(X,y).','model.predict(X).','model.score(X,y).','model.get_params().'],['fit uses the training features and targets to estimate the model.','predict applies an already fitted model to features.','score evaluates a fitted model against targets; it does not replace the fitting step.','get_params exposes estimator configuration rather than fitting coefficients.'],'The training step is fit(X,y); prediction, scoring and parameter inspection have distinct roles.',assumptions=['Source-scoped estimator API workflow; X contains sample features and y the corresponding target values.'])
add(6,6,'Array dtype qualification','A NumPy array is explicitly created with dtype=object and stores the Python values 1 and "red". Which statement correctly qualifies the assignment’s array-versus-DataFrame comparison?',['The array still has one array dtype, object, while its referenced Python objects can have different types; DataFrame columns can each have their own dtype.','The array must have two separate top-level array dtypes because its Python objects differ.','Creating an object array forces every stored object to become a floating-point number.','A DataFrame must convert all columns to the same dtype whenever one column contains text.'],['One ndarray dtype does not mean identical Python object types; DataFrames support columnwise dtypes.','A single ndarray has one dtype descriptor, even when that dtype is object or structured.','An explicit object dtype stores object references rather than requiring numeric coercion.','A DataFrame can retain heterogeneous column dtypes.'],'Distinguish the array’s dtype descriptor from the types of objects stored under dtype=object. The source’s short “same type” claim needs that qualification.',assumptions=['Added object-array counterexample; structured dtypes also require care, but no claim that every array stores one primitive numeric type is made.'])
add(6,7,'Squared-error regression leaf','A regression-tree leaf contains unweighted training targets [12,15,18,20,25]. Under a squared-error constant-leaf model, what prediction minimizes the leaf loss?',['18.','20.','12.','25.'],['The mean is (12+15+18+20+25)/5=18.','Twenty is one sample, not the loss-minimizing mean.','The minimum sample is not generally the squared-error minimizer.','The maximum sample is not generally the squared-error minimizer.'],'The unweighted mean minimizes the sum of squared deviations. This rule depends on the stated loss and weighting.',typ='numerical',kinds={26:'equation'},assumptions=['Unweighted scalar targets and squared-error loss; do not generalize this prediction rule to every tree criterion.'],steps=['Sum the targets: 90.','Divide by five: 18.'],formulas=[formula('ŷ_leaf=(1/n)Σ_i y_i',{'ŷ_leaf':'constant prediction in the leaf','n':'number of leaf training samples','y_i':'target of sample i','i':'sample index from 1 to n'},{'ŷ_leaf,y_i':'target units','n,i':'dimensionless'},['Unweighted squared-error constant prediction; n>0.'])])
add(6,8,'Tree route and leaf average','Use the assignment tree: root test x₁≤10 has true leaf [3,5,7]; its false branch tests x₂≤5, with true leaf [10,14,18] and false leaf [30,40]. For (x₁,x₂)=(12,3), what is the unweighted squared-error prediction?',['14.','5.','35.','10.'],['12 fails the root test and 3 passes the second test; mean(10,14,18)=14.','This chooses the root’s true leaf despite x₁=12.','This reverses the second branch despite x₂=3≤5.','This selects one target instead of averaging the selected leaf.'],'Follow both inequalities in order, then average only the samples in the reached leaf.',typ='diagram',difficulty='medium',kinds={26:'figure',27:'derivation'},locs={26:'Week 6 item 8, complete regression-tree diagram and its two branch tests',27:'Week 6 item 8, continued input and leaf-mean calculation'},assumptions=['The source tree is restated to remain usable without opening the preview; ordinary unweighted squared-error leaf predictions.'],steps=['12≤10 is false, so move to the x₂ test.','3≤5 is true, so reach [10,14,18].','Prediction=(10+14+18)/3=14.'],formulas=[formula('ŷ_leaf=(1/n)Σ_i y_i',{'ŷ_leaf':'constant prediction in the reached leaf','n':'sample count in that leaf','y_i':'training target in that leaf','i':'sample index'},{'ŷ_leaf,y_i':'target units','n,i':'dimensionless'},['Use only the reached leaf and unweighted squared error.'])])
add(6,9,'Policy versus reward and value','Which RL object specifies how an agent selects an action in a state, possibly by assigning probabilities to available actions?',['A policy π(a|s).','The immediate reward function r(s,a).','The state-value function V(s).','The transition model P(s′|s,a).'],['A policy is an action-selection rule or conditional action distribution.','Reward evaluates an outcome or state-action situation, rather than specifying action selection by itself.','Value estimates expected return under a policy, not the action-selection distribution itself.','The transition model predicts next states given state/action rather than choosing actions.'],'A policy maps states to actions or action probabilities; it is distinct from rewards, values and dynamics.',assumptions=['s is a state, a an action and s′ a subsequent state. Deterministic policies are a special case.'])
add(6,10,'Q update and terminal target','The assignment gives Q_old=4, reward r=3, learning rate α=0.1, discount γ=0.9 and max_a Q(s′,a)=10. What are the updated values for (i) a nonterminal next state and (ii) an added terminal-transition version that does not bootstrap?',['(i) 4.8; (ii) 3.9.','(i) 12; (ii) 3.','(i) 4.8; (ii) 4.8.','(i) 5.2; (ii) 4.3.'],['The nonterminal target is 12 and error 8, giving 4.8; the terminal target is 3 and error −1, giving 3.9.','This replaces the old estimate entirely with each target and ignores α=0.1.','This incorrectly retains a next-state value for the declared terminal case.','This adds α times the target without subtracting the old estimate in the TD error.'],'Use the old estimate plus a learning-rate-scaled target error; the terminal version drops only the bootstrap term, not the reward.',typ='numerical',difficulty='medium',kinds={27:'equation',28:'derivation'},assumptions=['Original supplied next-state value is nonterminal; the second case is an explicitly added terminal comparison. Values and reward use consistent units.'],steps=['Nonterminal target=3+0.9·10=12, so Q_new=4+0.1(12−4)=4.8.','Terminal target=3, so Q_new=4+0.1(3−4)=3.9.'],formulas=[formula('Q_new=Q_old+α[r+γ max_a Q(s′,a)−Q_old]',{'Q_new,Q_old':'updated and prior state-action estimates','α':'learning rate','r':'immediate reward','γ':'discount factor','s′':'next state','a':'available next-state action','Q(s′,a)':'next-state action-value estimate'},{'Q_new,Q_old,r,Q(s′,a)':'consistent reward/value units','α,γ':'dimensionless','s′,a':'state/action identifiers'},['For terminal next states replace the bootstrap term γ max_a Q(s′,a) by zero.'])])
# Pre-freeze source-kind/locator and pedagogical pass; not independent approval.
def q(w,n):return next(q for q in BATCHES[w]['questions']if q['id'].endswith(f'Q{n:03d}'))
def op(w,n,oid,text,reason):
 x=q(w,n);next(o for o in x['options']if o['id']==oid)['text']=text;x['solution']['optionExplanations'][oid]=reason
# Keep distractors in the same software/design domains rather than unrelated terminology.
op(1,9,'o2','Inheritance: the speech component must be a subclass of the navigation component.','Separate interacting modules do not require the implementation inheritance asserted here.')
op(1,9,'o3','Tight coupling: each component must directly modify the other’s internal state.','Agreed interfaces allow separation rather than requiring direct access to internal state.')
op(1,9,'o4','Code duplication: both components must independently reimplement the same complete system.','Separate responsibilities do not require duplicating the full system in each component.')
op(1,10,'o2','URDF alone maintains a time-indexed history of observed camera-to-base poses; TF only stores link geometry.','This exchanges live transform handling with structural model roles.')
op(1,10,'o3','A URDF camera-mount origin must change automatically whenever the camera moves, even without a transform publisher.','A structural description does not automatically observe and publish a changing pose history.')
op(1,10,'o4','A single fixed camera-to-base transform is sufficient even when that relative pose changes with time.','A fixed transform cannot represent the stated changing relationship at requested timestamps.')
op(2,8,'o2','An interior singularity lies on the workspace boundary, whereas a boundary singularity lies strictly inside it.','This reverses the source’s spatial classification.')
op(2,8,'o3','An interior singularity is any point close to the base, even when its Jacobian retains full relevant rank.','Being close to the base alone does not establish singularity.')
op(2,8,'o4','A boundary singularity is defined solely by a joint-limit setting, even when no relevant Jacobian rank is lost.','A joint-limit constraint and a kinematic Jacobian singularity are different conditions.')
