# Every citation contains text from its own page, never a cross-page excerpt attached to a wrong location.
for w,b in BATCHES.items():
 for x in b['questions']:
  n=int(x['id'][-3:]);item=ITEMS[x['assignmentSourceItemId']]
  for c in x['citations']:
   c['evidenceText']=(R/f"sources/text/assignments/page-{c['physicalPage']:04d}.txt").read_text().strip()
   if 'prompt and choices' in c['locator']:c['locator']=c['locator'].replace('prompt and choices','item region beginning with the prompt, including the content visible on this page')
  x['solution']['misconceptions']=[x['solution']['optionExplanations'][o['id']]for o in x['options']if o['id']not in x['correctOptionIds']]
  # Remap IDs without changing text or answer semantics to avoid a fixed correct-ID convention.
  shift=(w+n)%4;mp={f'o{i+1}':f'o{(i+shift)%4+1}'for i in range(4)}
  for o in x['options']:o['id']=mp[o['id']]
  x['correctOptionIds']=[mp[i]for i in x['correctOptionIds']];x['solution']['optionExplanations']={mp[k]:v for k,v in x['solution']['optionExplanations'].items()}
 write(f"data/question-batches/{b['batchId']}.json",b)
 ins=json.loads((R/f"data/inspection-batches/{b['batchId']}.json").read_text())
 for s in ins['slides']:s['conceptIds']=[c['id']for c in b['concepts']if s['id']in c['slideIds']]
 write(f"data/inspection-batches/{b['batchId']}.json",ins)
